	return
import sys
name = unicode(event.name)
# Role names match case-insensitively: removeRole('default', 'ADMINISTRATOR') removes it.
# So only act on a name spelled exactly as the catalog has it.
if name not in [unicode(r) for r in system.user.getRoles('default')]:
	self.view.custom.lastEvent = 'onRoleDelete REFUSED: no role named "' + name + '"'
elif name == 'Administrator':
	self.view.custom.lastEvent = 'onRoleDelete REFUSED: the demo keeps the Administrator role'
else:
	try:
		resp = system.user.removeRole('default', name)
		errs = [unicode(x) for x in resp.getErrors()]
		if errs:
			self.view.custom.lastEvent = 'onRoleDelete ERRORS: ' + '; '.join(errs)
		else:
			self.view.custom.lastEvent = 'onRoleDelete removed "' + name + '"'
	except:
		self.view.custom.lastEvent = 'onRoleDelete FAILED: ' + unicode(sys.exc_info()[1])
self.view.custom.refreshTick = self.view.custom.refreshTick + 1

